# Extract 4-color source cells, test occurrence unions under orientations
from itertools import product

def shape_coords(A,color):
 pts=np.argwhere(A==color); mn=pts.min(0); return {tuple(p-mn) for p in pts}
def orient(sh):
 outs=[]
 for refl in [False,True]:
  q={(r, -c if refl else c) for r,c in sh}
  for k in range(4):
   if k: q={(c,-r) for r,c in q}
   mn=(min(r for r,c in q),min(c for r,c in q))
   norm=frozenset((r-mn[0],c-mn[1]) for r,c in q)
   if norm not in outs: outs.append(norm)
 return outs
def stamp(A, color, bg, ori_set):
 sh=shape_coords(A,color); H,W=A.shape; out=np.zeros_like(A,dtype=bool)
 for s in [sh] if ori_set=='fixed' else orient(sh):
  h=max(r for r,c in s)+1; w=max(c for r,c in s)+1
  for r in range(H-h+1):
   for c in range(W-w+1):
    if all(A[r+dr,c+dc]==bg for dr,dc in s):
     for dr,dc in s: out[r+dr,c+dc]=1
 return out
